import{_ as e,c as t,o as a,ah as o}from"./chunks/framework.DX1DJjtl.js";const u=JSON.parse('{"title":"errors","description":"","frontmatter":{},"headers":[],"relativePath":"api/core/errors.md","filePath":"api/core/errors.md","lastUpdated":1785055892000}'),s={name:"api/core/errors.md"};function d(i,r,n,l,c,h){return a(),t("div",null,[...r[0]||(r[0]=[o('<h1 id="errors" tabindex="-1">errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;errors&quot;">​</a></h1><p>Error handling for Basalt 2.</p><p>errors.parse() turns an error + traceback into structured info and is side-effect free (testable). errors.show() renders the error screen; it must be called AFTER the terminal/palette has been cleaned up, so the message is never displayed with hijacked palette slots.</p><p>The screen highlights two locations:</p><ul><li>the error site (where it was thrown, often inside Basalt 2)</li><li>the first stack frame in USER code — that&#39;s usually the actual cause, so its source line is shown as an excerpt.</li></ul><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><h3 id="basalterrorinfo" tabindex="-1"><code>BasaltErrorInfo</code> <a class="header-anchor" href="#basalterrorinfo" aria-label="Permalink to &quot;`BasaltErrorInfo`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>message</td><td><code>string</code></td><td>Normalized error message</td></tr><tr><td>file <em>(optional)</em></td><td><code>string</code></td><td>Source file of the error site</td></tr><tr><td>line <em>(optional)</em></td><td><code>integer</code></td><td>Source line of the error site</td></tr><tr><td>userFile <em>(optional)</em></td><td><code>string</code></td><td>Source file of the first user-code frame</td></tr><tr><td>userLine <em>(optional)</em></td><td><code>integer</code></td><td>Source line of the first user-code frame</td></tr><tr><td>trace</td><td><code>string[]</code></td><td>Cleaned traceback lines</td></tr></tbody></table><h3 id="basaltwrappederror" tabindex="-1"><code>BasaltWrappedError</code> <a class="header-anchor" href="#basaltwrappederror" aria-label="Permalink to &quot;`BasaltWrappedError`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>err</td><td><code>any</code></td><td>Original error value</td></tr><tr><td>trace <em>(optional)</em></td><td><code>string</code></td><td>Captured traceback</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="errors-parse-err-trace" tabindex="-1">errors.parse(err, trace) <a class="header-anchor" href="#errors-parse-err-trace" aria-label="Permalink to &quot;errors.parse(err, trace)&quot;">​</a></h3><p>Normalizes an error value and traceback into displayable lines.</p><ul><li><p><strong>err</strong> (<code>any</code>) Error value</p></li><li><p><strong>trace</strong> (<code>string</code>, optional) Traceback text</p></li><li><p><strong>returns</strong> <strong>info</strong> (<code>BasaltErrorInfo</code>)</p></li></ul><h3 id="errors-show-err-trace-showtrace" tabindex="-1">errors.show(err, trace, showTrace) <a class="header-anchor" href="#errors-show-err-trace-showtrace" aria-label="Permalink to &quot;errors.show(err, trace, showTrace)&quot;">​</a></h3><p>Renders an error screen on the active terminal.</p><ul><li><strong>err</strong> (<code>any</code>) Error value</li><li><strong>trace</strong> (<code>string</code>, optional) Traceback text</li><li><strong>showTrace</strong> (<code>boolean</code>, optional) Whether traceback lines are shown</li></ul><h3 id="errors-wrap-err-trace" tabindex="-1">errors.wrap(err, trace) <a class="header-anchor" href="#errors-wrap-err-trace" aria-label="Permalink to &quot;errors.wrap(err, trace)&quot;">​</a></h3><p>Wraps an error and traceback for Basalt&#39;s protected event loop.</p><ul><li><p><strong>err</strong> (<code>any</code>) Error value</p></li><li><p><strong>trace</strong> (<code>string</code>, optional) Traceback text</p></li><li><p><strong>returns</strong> <strong>wrapped</strong> (<code>BasaltWrappedError</code>)</p></li></ul>',20)])])}const b=e(s,[["render",d]]);export{u as __pageData,b as default};
